  "question_count": 15,
  "questions": [
    {
      "id": "ALG04MICRO_001",
      "card_id": "alg04-core-1",
      "micro_role": "base",
      "question": "Biểu thức nào là đơn thức đã thu gọn?",
      "options": [
        "\\(-2x^2y^3\\)",
        "\\(3x^2y\\cdot y\\)",
        "\\(x+y\\)",
        "\\(\\frac1x\\)"
      ],
      "answer": 0,
      "tags": {
        "topic": "bieu-thuc-dai-so",
        "skill": [
          "nhan-biet-don-thuc"
        ],
        "type": "nhan-biet-don-thuc",
        "layer": "KNTT-Core",
        "grade": 7
      },
      "difficulty": "basic",
      "explanation": "\\(-2x^2y^3\\) đã ở dạng một tích giữa hệ số và các biến có số mũ nguyên không âm.",
      "hints": [
        "Đơn thức không có phép cộng/trừ giữa các hạng tử.",
        "Kiểm tra xem phần biến đã được gộp hết lũy thừa cùng cơ số chưa."
      ],
      "option_evidence": {
        "1": {
          "signal": "don-thuc-chua-thu-gon",
          "signal_weight": 1,
          "feedback_hint": "Biểu thức này vẫn còn phép nhân các phần biến có thể gộp lại."
        }
      },
      "curriculum": {
        "book": "KNTT",
        "grades": [
          7,
          8
        ],
        "level": "core"
      },
      "exam": {
        "entrance10": "foundation",
        "specialized": "none"
      }
    },
    {
      "id": "ALG04MICRO_002",
      "card_id": "alg04-core-1",
      "micro_role": "trap",
      "question": "Sau khi thu gọn, bậc của \\(P=2x^4-2x^4+3x^2+1\\) là bao nhiêu?",
      "options": [
        "2",
        "4",
        "1",
        "0"
      ],
      "answer": 0,
      "tags": {
        "topic": "bieu-thuc-dai-so",
        "skill": [
          "he-so-bac"
        ],
        "type": "he-so-bac",
        "layer": "KNTT-Core",
        "grade": 7
      },
      "difficulty": "intermediate",
      "explanation": "Hai hạng tử \\(2x^4\\) và \\(-2x^4\\) triệt tiêu. Còn \\(3x^2+1\\), nên bậc là 2.",
      "hints": [
        "Phải thu gọn đa thức trước khi xác định bậc.",
        "Hai hạng tử bậc 4 có hệ số đối nhau."
      ],
      "option_evidence": {
        "1": {
          "signal": "bac-da-thuc-chua-thu-gon",
          "signal_weight": 2,
          "feedback_hint": "Em đang lấy bậc trước khi thu gọn các hạng tử đồng dạng."
